      primary: '子供の＿＿＿＿、よく漢字を知っていますね。',
      romaji: '(答え: わりに / Wari ni)',
      meaning: 'उत्तर: わりに。(बच्चाको तुलनामा, राम्रोसँग कान्जी थाहा रहेछ नि。)',
      note: '文法: 〜わりに(...को तुलनामा अनपेक्षित रूपमा, आश्चर्यजनक भिन्नता जनाउँदा)',
    ),
    LessonItem(
      primary: '疲れすぎて、歩く＿＿＿＿できません。',
      romaji: '(答え: ことさえ / Koto sae)',
      meaning: 'उत्तर: ことさえ。(यति थाकेको छु कि, हिँड्न सम्म पनि सक्दिनँ。)',
      note: '文法: 〜さえ(...सम्म पनि, चरम उदाहरण देखाएर जोड दिँदा)',
    ),
    LessonItem(
      primary: 'もう時間がないので、急ぐ＿＿＿＿。',
      romaji: '(答え: しかありません / Shika arimasen)',
      meaning: 'उत्तर: しかありません。(अब समय नभएकाले, हतार गर्नु बाहेक अरू उपाय छैन。)',
      note: '文法: 〜しかありません(...बाहेक अरू उपाय छैन)',
    ),
    LessonItem(
      primary: 'この店は値段が安い＿＿＿＿、味もいいです。',
      romaji: '(答え: ばかりでなく / Bakari denaku)',
      meaning: 'उत्तर: ばかりでなく。(यो पसलमा मूल्य सस्तो मात्र होइन, स्वाद पनि राम्रो छ。)',
      note: '文法: 〜ばかりでなく(...मात्र होइन)、後に「〜も」を伴うことが多い',
    ),
    LessonItem(
      primary: 'こんなに練習したのだから、次の試合は勝つ＿＿＿＿。',
      romaji: '(答え: に決まっています / Ni kimatte imasu)',
      meaning: 'उत्तर: に決まっています。(यति अभ्यास गरेको हुनाले, अर्को खेल पक्कै जित्छौं。)',
      note: '文法: 〜に決まっています(पक्कै...हुन्छ, बोल्नेको दृढ विश्वास/अनुमान)',
    ),
  ],

